const clone=value=>structuredClone(value),hash=value=>createHash('sha256').update(value).digest('hex');
const projectId='alternatives-test',before=':root { --radius: 8px; }\nbutton { border-radius: var(--radius); }\n';
const file={path:'src/theme.css',source:before,revision:hash(before).slice(0,16)},token=listDesignTokens([file])[0],featureId=randomUUID(),screenId=randomUUID(),scenarioId=randomUUID(),timestamp=new Date().toISOString();
const proposal=createTokenProposal({file,name:token.name,occurrence:token.occurrence,value:'12px',projectId});
proposal.designImpact={version:1,result:await analyzeChangeImpact({projectId,target:{kind:'token',path:file.path,revision:file.revision,name:token.name,occurrence:token.occurrence},files:[file]}),relatedScenarios:[{featureId,featureTitle:'Profile',screenId,screenTitle:'Profile screen',scenarioId,scenarioTitle:'Save',paths:[file.path],suiteNames:[]}]};
